import { Monitor, Moon, Sun } from '@phosphor-icons/react';
import { ToggleGroup } from '@/components/ToggleGroup';
import { useTheme, type ThemeMode } from '@/components/Theme';

function ColourMode() {
  const { mode, setMode } = useTheme();
  return (
    <ToggleGroup aria-label="Colour mode" size="sm" value={mode} onValueChange={(next) => setMode(next as ThemeMode)}>
      <ToggleGroup.Item value="system"><Monitor aria-hidden />System</ToggleGroup.Item>
      <ToggleGroup.Item value="light"><Sun aria-hidden />Light</ToggleGroup.Item>
      <ToggleGroup.Item value="dark"><Moon aria-hidden />Dark</ToggleGroup.Item>
    </ToggleGroup>
  );
}

<Theme defaultMode="system">
  <ColourMode />
</Theme>

import { Moon, Sun } from '@phosphor-icons/react';
import { IconButton } from '@/components/IconButton';
import { useTheme } from '@/components/Theme';

function ColourModeButton() {
  const { resolvedMode, setMode } = useTheme();
  return (
    <IconButton aria-label={resolvedMode === 'dark' ? 'Switch to light mode' : 'Switch to dark mode'} onClick={() => setMode(resolvedMode === 'dark' ? 'light' : 'dark')}>
      {resolvedMode === 'dark' ? <Sun aria-hidden /> : <Moon aria-hidden />}
    </IconButton>
  );
}

<Theme defaultMode="system">
  <ColourModeButton />
</Theme>
